    fn __data1() -> Py { py_tuple(vec![py_str("stopped working"), py_str("stops working"), py_str("stopped work"), py_str("not working"), py_str("isnt working"), py_str("isn't working"), py_str("doesnt work"), py_str("doesn't work"), py_str("wont work"), py_str("won't work"), py_str("no longer works"), py_str("broken"), py_str("broke"), py_str("broken down"), py_str("broke down"), py_str("packed in"), py_str("packed up"), py_str("gave up"), py_str("dead"), py_str("no power"), py_str("wont come on"), py_str("won't come on"), py_str("wont turn on"), py_str("won't turn on"), py_str("wont switch on"), py_str("won't switch on"), py_str("faulty"), py_str("gone wrong"), py_str("went wrong")]) }
